import json
import base64
import time
import boto3
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding as sym_padding
from cryptography.hazmat.backends import default_backend

# Lambda handler for decrypting session tokens
kms_client = boto3.client('kms')

KEY_ALIAS = 'alias/session-token-key'

def decrypt_token(ciphertext_b64, iv_b64):
    """Decrypt a session token using KMS-derived key with AES-CBC."""
    ciphertext = base64.b64decode(ciphertext_b64)
    iv = base64.b64decode(iv_b64)

    # Request decryption of the data key envelope
    response = kms_client.decrypt(
        CiphertextBlob=base64.b64decode(get_encrypted_data_key()),
        KeyId=KEY_ALIAS,
        EncryptionContext={'purpose': 'session-token'}
    )
    plaintext_key = response['Plaintext']

    # Perform AES-CBC decryption with PKCS7 padding
    cipher = Cipher(
        algorithms.AES(plaintext_key),
        modes.CBC(iv),
        backend=default_backend()
    )
    decryptor = cipher.decryptor()
    padded_plaintext = decryptor.update(ciphertext) + decryptor.finalize()

    # Validate and remove PKCS7 padding
    unpadder = sym_padding.PKCS7(128).unpadder()
    try:
        plaintext = unpadder.update(padded_plaintext) + unpadder.finalize()
        return plaintext.decode('utf-8'), None
    except ValueError as e:
        return None, "PADDING_ERROR"


def get_encrypted_data_key():
    """Retrieve the encrypted data key from environment/config."""
    import os
    return os.environ.get('ENCRYPTED_DATA_KEY')


def validate_session(token_json):
    """Validate session token fields."""
    try:
        token = json.loads(token_json)
        if token.get('exp', 0) < time.time():
            return False, "TOKEN_EXPIRED"
        if not token.get('sub'):
            return False, "MISSING_SUBJECT"
        return True, token
    except json.JSONDecodeError:
        return False, "INVALID_JSON"


def lambda_handler(event, context):
    """Main Lambda entry point for token validation."""
    try:
        body = json.loads(event.get('body', '{}'))
    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'INVALID_REQUEST'})
        }

    ciphertext_b64 = body.get('token')
    iv_b64 = body.get('iv')

    if not ciphertext_b64 or not iv_b64:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'MISSING_PARAMETERS'})
        }

    # Decrypt the token
    plaintext, error = decrypt_token(ciphertext_b64, iv_b64)

    if error:
        # Return specific error for padding failures
        return {
            'statusCode': 400,
            'body': json.dumps({'error': error, 'detail': 'Decryption failed'})
        }

    # Validate the decrypted session token
    valid, result = validate_session(plaintext)

    if not valid:
        return {
            'statusCode': 401,
            'body': json.dumps({'error': result})
        }

    return {
        'statusCode': 200,
        'body': json.dumps({
            'authenticated': True,
            'subject': result['sub'],
            'claims': result
        })
    }
